-- 544: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 6 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_544_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_544_guard;
INSERT INTO _migration_544_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_026' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Factorise x² + 7x + 12.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. (x + 2)(x + 6)","B. (x + 3)(x + 4)","C. (x − 3)(x − 4)","D. (x + 1)(x + 12)"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Find two numbers that multiply to 12 and add to 7: they are 3 and 4. Hence x² + 7x + 12 = (x + 3)(x + 4). ((x + 2)(x + 6) adds to 8, and (x − 3)(x − 4) gives −7x.) Therefore the correct answer is B: (x + 3)(x + 4).' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Factorise' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_026' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_544_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_027' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Given that y = x² + 1, find the value of y when x = 3.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 7","B. 9","C. 10","D. 4"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Substitute x = 3: y = 3² + 1 = 9 + 1 = 10. (7 treats x² as 2x; 9 forgets to add 1.) Therefore the correct answer is C: 10.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_027' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_544_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_028' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Write down the sum of the roots of the equation x² − 6x + 8 = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. −6","B. 8","C. −8","D. 6"]' AND q.correct_answer IS 'D' AND q.explanation IS 'For ax² + bx + c = 0 the sum of the roots is −b/a. Here −b/a = −(−6)/1 = 6. (8 is the product of the roots, c/a — a common mix-up; −6 forgets the leading minus.) Therefore the correct answer is D: 6.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write down' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_028' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_544_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_029' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation x² − 9 = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 3 or x = −3","B. x = 3 only","C. x = 9 or x = −9","D. x = 81"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Factorise the difference of two squares: (x − 3)(x + 3) = 0, so x = 3 or x = −3. (x = 3 only forgets the negative square root of 9; x = ±9 forgets to take the square root.) Therefore the correct answer is A: x = 3 or x = −3.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_029' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_544_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_030' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation x² − 7x + 10 = 0 by factorisation.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = −2 or x = −5","B. x = 2 or x = 5","C. x = 1 or x = 10","D. x = −2 or x = 5"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Two numbers that multiply to 10 and add to −7 are −2 and −5, so x² − 7x + 10 = (x − 2)(x − 5) = 0, giving x = 2 or x = 5. Check: 2 + 5 = 7 and 2 × 5 = 10. (x = −2 or x = −5 solves x² + 7x + 10 = 0 instead.) Therefore the correct answer is B: x = 2 or x = 5.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_030' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_026', 'topic_wassce_p2_math_qdr', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Factorise x² + 7x + 12.', 'multiple_choice', NULL, '["A. (x + 2)(x + 6)","B. (x + 3)(x + 4)","C. (x − 3)(x − 4)","D. (x + 1)(x + 12)"]', 'B', 'Find two numbers that multiply to 12 and add to 7: they are 3 and 4. Hence x² + 7x + 12 = (x + 3)(x + 4). ((x + 2)(x + 6) adds to 8, and (x − 3)(x − 4) gives −7x.) Therefore the correct answer is B: (x + 3)(x + 4).', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Factorise', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_027', 'topic_wassce_p2_math_qdr', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Given that y = x² + 1, find the value of y when x = 3.', 'multiple_choice', NULL, '["A. 7","B. 9","C. 10","D. 4"]', 'C', 'Substitute x = 3: y = 3² + 1 = 9 + 1 = 10. (7 treats x² as 2x; 9 forgets to add 1.) Therefore the correct answer is C: 10.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Evaluate', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_028', 'topic_wassce_p2_math_qdr', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Write down the sum of the roots of the equation x² − 6x + 8 = 0.', 'multiple_choice', NULL, '["A. −6","B. 8","C. −8","D. 6"]', 'D', 'For ax² + bx + c = 0 the sum of the roots is −b/a. Here −b/a = −(−6)/1 = 6. (8 is the product of the roots, c/a — a common mix-up; −6 forgets the leading minus.) Therefore the correct answer is D: 6.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Write down', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_029', 'topic_wassce_p2_math_qdr', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation x² − 9 = 0.', 'multiple_choice', NULL, '["A. x = 3 or x = −3","B. x = 3 only","C. x = 9 or x = −9","D. x = 81"]', 'A', 'Factorise the difference of two squares: (x − 3)(x + 3) = 0, so x = 3 or x = −3. (x = 3 only forgets the negative square root of 9; x = ±9 forgets to take the square root.) Therefore the correct answer is A: x = 3 or x = −3.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_030', 'topic_wassce_p2_math_qdr', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation x² − 7x + 10 = 0 by factorisation.', 'multiple_choice', NULL, '["A. x = −2 or x = −5","B. x = 2 or x = 5","C. x = 1 or x = 10","D. x = −2 or x = 5"]', 'B', 'Two numbers that multiply to 10 and add to −7 are −2 and −5, so x² − 7x + 10 = (x − 2)(x − 5) = 0, giving x = 2 or x = 5. Check: 2 + 5 = 7 and 2 × 5 = 10. (x = −2 or x = −5 solves x² + 7x + 10 = 0 instead.) Therefore the correct answer is B: x = 2 or x = 5.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-core-math-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_wcms3_026', 'q_wcms3_027', 'q_wcms3_028', 'q_wcms3_029', 'q_wcms3_030');
